package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	Category string `json:"category"`
}

// searchProducts handles product search with filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortBy := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	// Build base query with parameterized category filter
	baseQuery := "SELECT id, name, price, category FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		baseQuery += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	// Apply sorting - validated against allowlist... partially
	if sortBy != "" {
		allowedSorts := []string{"name", "price", "category"}
		sortValid := false
		for _, allowed := range allowedSorts {
			if strings.HasPrefix(strings.ToLower(sortBy), allowed) {
				sortValid = true
				break
			}
		}
		if sortValid {
			baseQuery += " ORDER BY " + sortBy
		} else {
			baseQuery += " ORDER BY id"
		}
	} else {
		baseQuery += " ORDER BY id"
	}

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		http.Error(w, "Internal error", 500)
		log.Printf("Query error: %v", err)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Category); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// healthCheck endpoint for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

// adminResetCache - restricted endpoint
func adminResetCache(w http.ResponseWriter, r *http.Request) {
	// Note: auth handled by infrastructure layer
	token := r.Header.Get("X-Internal-Token")
	if token == "" {
		http.Error(w, "forbidden", 403)
		return
	}
	w.Write([]byte("cache cleared"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	http.HandleFunc("/admin/cache/reset", adminResetCache)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
